const compiledBySchema = new WeakMap<Record<string, unknown>, ValidateFunction>();

function validatorFor(toolName: string, schema: Record<string, unknown>): ValidateFunction {
  const cached = compiledBySchema.get(schema);
  if (cached) return cached;
  const compiled = compileSchema(toolName, schema);
  compiledBySchema.set(schema, compiled);
  return compiled;
}

// Built from the property path and ajv's constraint message only: ajv's messages for the
// keywords this validates never embed the rejected value, so nothing here echoes input data.
function describeFailures(errors: ErrorObject[]): string[] {
  return errors.map(error => {
    if (error.keyword === 'required') {
      const missing = (error.params as {missingProperty: string}).missingProperty;
      return `${joinPath(error.instancePath, missing)} is required`;
    }
    return `${joinPath(error.instancePath)} ${error.message ?? 'is invalid'}`;
  });
}

function joinPath(instancePath: string, property?: string): string {
  const segments = instancePath.split('/').filter(Boolean);
  if (property !== undefined) segments.push(property);
  return segments.length ? segments.join('.') : '(input)';
}
